-- Phase T6 (docs/phase-t-design.md section 6, as changed in T6): payments in
-- the settlement window. Generated by prisma migrate diff, read before use.
-- payment gains location_id (the sale's, enforced by the new composite foreign
-- key to sale (business_id, id, location_id)), recorded_by_device_id, txid and
-- reversed_txid; field_settlement gains earlier_sales_cash.
-- The NOT NULL columns have no default on purpose: there is no real data yet
-- (dev and test hold no payments or settlements; no hosted database exists).
-- On a table with rows this fails with Postgres's own NOT NULL error.

-- DropForeignKey
ALTER TABLE "payment" DROP CONSTRAINT "payment_business_id_sale_id_fkey";

-- AlterTable
ALTER TABLE "field_settlement" ADD COLUMN     "earlier_sales_cash" DECIMAL(14,2) NOT NULL;

-- AlterTable
ALTER TABLE "payment" ADD COLUMN     "location_id" UUID NOT NULL,
ADD COLUMN     "recorded_by_device_id" UUID NOT NULL,
ADD COLUMN     "reversed_txid" xid8,
ADD COLUMN     "txid" xid8 NOT NULL DEFAULT pg_current_xact_id();

-- CreateIndex
CREATE INDEX "payment_business_id_location_id_idx" ON "payment"("business_id", "location_id");

-- CreateIndex
CREATE UNIQUE INDEX "sale_business_id_id_location_id_key" ON "sale"("business_id", "id", "location_id");

-- AddForeignKey
ALTER TABLE "payment" ADD CONSTRAINT "payment_business_id_sale_id_location_id_fkey" FOREIGN KEY ("business_id", "sale_id", "location_id") REFERENCES "sale"("business_id", "id", "location_id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "payment" ADD CONSTRAINT "payment_business_id_recorded_by_device_id_fkey" FOREIGN KEY ("business_id", "recorded_by_device_id") REFERENCES "device"("business_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

